"""Per-stream replay engine: atomic sparse patch updates, routing
replacements, frozen repairs with memoization, and later validation."""

from .dtp import compute_repair
from .snapshot_cache import RepairCache, copy_publication
from .topology import Topology
from .validate import validate_frozen

MISSING = object()

CELL_KEYS = frozenset(("perturbed", "ground_truth", "corrected", "confidence"))

DEMAND_MAX = 10 ** 9


class Routes:
    """Active routing plan: null or full per-pair weighted path bundles."""

    def __init__(self, raw, topo):
        if raw is None:
            self.bundles = None
            self.key = None
            return
        bundles = {}
        entries = []
        for sname, dbundle in raw.items():
            sid = topo.id_of[sname]
            for dname, items in dbundle.items():
                did = topo.id_of[dname]
                lst = []
                for item in items:
                    path = tuple(item["path"])
                    weight = item["weight"]
                    lst.append((path, weight))
                    entries.append((sname, dname, path, weight))
                bundles[(sid, did)] = tuple(lst)
        self.bundles = bundles
        self.key = tuple(sorted(entries))

    def internal_predictions(self, topo, demands):
        """Floor after all contributions; never clamped here."""
        acc = {}
        for (sid, did), items in self.bundles.items():
            demand = demands.get((sid, did), 0)
            if demand == 0:
                continue
            for (path, weight) in items:
                contrib = demand * weight
                for a, b in zip(path, path[1:]):
                    fi = topo.flow_index[(topo.id_of[a], topo.id_of[b])]
                    acc[fi] = acc.get(fi, 0) + contrib
        total = len(topo.flows)
        return [acc.get(i, 0) // 1000 for i in range(total)]


def _is_int(value):
    return type(value) is int


class Stream:
    def __init__(self, raw):
        self.topo = Topology(raw["topology"])
        settings = raw["settings"]
        self.trials = settings["trials"]
        self.epsilon = settings["epsilon"]
        self.seed = settings["seed"]
        self.cutoff = (settings["cutoff"][0], settings["cutoff"][1])
        self.bias = settings["bias"]
        self.tau = settings["tau"]
        self.gamma = (settings["gamma"][0], settings["gamma"][1])
        self.cache_slots = settings["cache_slots"]

        self.counters = {key: MISSING for key in self.topo.all_keys}
        self.demands = {pair: 0 for pair in self.topo.demand_pairs}
        self.routes = None
        self.cache = RepairCache(self.cache_slots)
        self.snapshots = {}
        self.wmemo = {}
        self._predictions = None

    # ------------------------------------------------------------- events
    def apply(self, event):
        op = event.get("op")
        if op == "patch":
            return self.do_patch(event)
        if op == "routes":
            return self.do_routes(event)
        if op == "repair":
            return self.do_repair(event)
        if op == "validate":
            return self.do_validate(event)
        return {"op": op if isinstance(op, str) else ""}

    def do_patch(self, event):
        if set(event.keys()) != {"op", "demands", "counters"}:
            return {"op": "patch", "accepted": False}
        demands = event["demands"]
        counters = event["counters"]
        if type(demands) is not list or type(counters) is not dict:
            return {"op": "patch", "accepted": False}
        topo = self.topo
        seen = set()
        demand_updates = []
        for entry in demands:
            if type(entry) is not list or len(entry) != 3:
                return {"op": "patch", "accepted": False}
            s, d, value = entry
            if not (_is_int(s) and _is_int(d) and _is_int(value)):
                return {"op": "patch", "accepted": False}
            if s == d or s not in topo.external_set or d not in topo.external_set:
                return {"op": "patch", "accepted": False}
            if (s, d) in seen:
                return {"op": "patch", "accepted": False}
            seen.add((s, d))
            if value < 0 or value > DEMAND_MAX:
                return {"op": "patch", "accepted": False}
            demand_updates.append((s, d, value))
        counter_updates = []
        for key, cell in counters.items():
            owner = topo.key_owner.get(key)
            if owner is None:
                return {"op": "patch", "accepted": False}
            if cell is None:
                counter_updates.append((key, MISSING))
                continue
            if type(cell) is not dict:
                return {"op": "patch", "accepted": False}
            if "perturbed" not in cell:
                return {"op": "patch", "accepted": False}
            if not set(cell.keys()) <= CELL_KEYS:
                return {"op": "patch", "accepted": False}
            perturbed = cell["perturbed"]
            if perturbed is None:
                counter_updates.append((key, MISSING))
                continue
            if not _is_int(perturbed):
                return {"op": "patch", "accepted": False}
            if perturbed < 0 or perturbed > topo.caps[owner]:
                return {"op": "patch", "accepted": False}
            counter_updates.append((key, perturbed))
        for (s, d, value) in demand_updates:
            self.demands[(s, d)] = value
        for (key, value) in counter_updates:
            self.counters[key] = value
        self._predictions = None
        return {"op": "patch", "accepted": True}

    def do_routes(self, event):
        self.routes = Routes(event["paths"], self.topo)
        self._predictions = None
        return {"op": "routes", "accepted": True}

    def do_repair(self, event):
        rid = event["id"]
        key = self.cache_key()
        hit = self.cache.get(key)
        if hit is not None:
            publication = hit
            cache_hit = True
        else:
            publication = self.build_repair()
            self.cache.put(key, copy_publication(publication))
            cache_hit = False
        self.snapshots[rid] = copy_publication(publication)
        links, order, counters = publication
        return {
            "op": "repair",
            "id": rid,
            "cache_hit": cache_hit,
            "links": [list(item) for item in links],
            "order": [list(item) for item in order],
            "counters": {
                key: {"corrected": value, "confidence": [num, den]}
                for (key, value, num, den) in counters
            },
        }

    def do_validate(self, event):
        rid = event["id"]
        publication = self.snapshots.get(rid)
        if publication is None:
            return {
                "op": "validate",
                "id": rid,
                "checked": 0,
                "passed": 0,
                "consistent": None,
                "failed": [],
            }
        checked, passed, consistent, failed = validate_frozen(
            self.topo, publication, self.predictions(),
            self.cutoff, self.bias, self.tau, self.gamma,
        )
        return {
            "op": "validate",
            "id": rid,
            "checked": checked,
            "passed": passed,
            "consistent": consistent,
            "failed": failed,
        }

    # ----------------------------------------------------------- helpers
    def cache_key(self):
        topo = self.topo
        counters_key = tuple(
            None if self.counters[key] is MISSING else self.counters[key]
            for key in topo.all_keys
        )
        demands_key = tuple(self.demands[pair] for pair in topo.demand_pairs)
        routes_key = None if self.routes is None else self.routes.key
        return (
            topo.signature,
            counters_key,
            demands_key,
            routes_key,
            self.seed,
            self.trials,
            self.epsilon,
        )

    def predictions(self):
        """(internal list or None, external list) indexed by flow index."""
        if self._predictions is not None:
            return self._predictions
        topo = self.topo
        out_marg = {eid: 0 for eid in topo.external_ids}
        in_marg = {eid: 0 for eid in topo.external_ids}
        for (s, d), value in self.demands.items():
            out_marg[s] += value
            in_marg[d] += value
        external = [0] * len(topo.flows)
        for i, (a, b) in enumerate(topo.flows):
            if a == -1:
                external[i] = out_marg[b]
            elif b == -1:
                external[i] = in_marg[a]
        internal = None
        if self.routes is not None:
            internal = self.routes.internal_predictions(topo, self.demands)
            for i, (a, b) in enumerate(topo.flows):
                if a == -1 or b == -1:
                    internal[i] = external[i]
        self._predictions = (internal, external)
        return self._predictions

    def build_repair(self):
        topo = self.topo
        internal, external = self.predictions()
        report_pools = []
        pred_votes = []
        for i, (a, b) in enumerate(topo.flows):
            pool = []
            for key in topo.counter_keys[i]:
                value = self.counters.get(key, MISSING)
                if value is not MISSING:
                    pool.append(value)
            report_pools.append(pool)
            if self.routes is None:
                pred_votes.append(None)
            else:
                vote = external[i] if (a == -1 or b == -1) else internal[i]
                cap = topo.caps[i]
                if vote > cap:
                    vote = cap
                pred_votes.append(vote)
        return compute_repair(
            topo, report_pools, pred_votes,
            self.seed, self.trials, self.epsilon, self.wmemo,
        )
